#!/bin/sh
# DynAllow agent installer for a Docker host / Proxmox LXC.
# Generated by the control server for site __AGENT_UID__. Contains a ONE-TIME
# provisioning profile and deletes itself after use.
#
#   sudo sh dynallow-__AGENT_UID__.sh                 install
#   sudo sh dynallow-__AGENT_UID__.sh --upgrade       preserve an existing identity
#   sudo sh dynallow-__AGENT_UID__.sh --reprovision   replace an existing identity
set -eu
DIR="${DYNALLOW_DIR:-/opt/dynallow-agent}"
SELF="$0"

say()  { printf '%s\n' "$*"; }
fail() { say "ERROR: $*"; say "Nothing was changed."; exit 1; }
burn() { # the installer holds a live credential
    if command -v shred >/dev/null 2>&1; then shred -u "$SELF" 2>/dev/null || rm -f "$SELF"; else rm -f "$SELF"; fi
}

[ "$(id -u)" = 0 ] || fail "run as root: sudo sh $SELF"
command -v docker >/dev/null 2>&1 || fail "Docker is not installed (see the README: 'Get Docker working')."
docker compose version >/dev/null 2>&1 || fail "the Docker Compose plugin is missing: apt install docker-compose-plugin"
docker info >/dev/null 2>&1 || fail "Docker is installed but not running, or this LXC needs nesting=1,keyctl=1 (see the README)."

# Releases before the rename installed into /opt/ipfailover-agent. Its identity
# counts as this host's existing state; it is moved, never copied or left behind.
LEGACY=/opt/ipfailover-agent
[ "$LEGACY" = "$DIR" ] && LEGACY=""
STATE="$DIR/data/state.json"
if [ -n "$LEGACY" ] && [ ! -f "$STATE" ] && [ -f "$LEGACY/data/state.json" ]; then STATE="$LEGACY/data/state.json"; fi

# Decide everything before touching anything, so a refusal really changes nothing.
case "${1:-}" in ""|--upgrade|--reprovision) ;; *) fail "unknown option: $1" ;; esac
if [ -f "$STATE" ] && [ "${1:-}" = "" ]; then
    fail "existing state found ($STATE); use --upgrade to preserve identity or --reprovision to replace it"
fi
if [ "${1:-}" = "--upgrade" ] && [ ! -f "$STATE" ]; then
    fail "--upgrade requires existing state.json"
fi
# Reject preexisting symlinks before root writes/chowns/moves anything.
for d in "$DIR" ${LEGACY:+"$LEGACY"}; do
    if [ -L "$d" ] || { [ -d "$d" ] && [ -n "$(find "$d" -type l -print -quit)" ]; }; then
        fail "$d contains symlinks"
    fi
done

# ===== From here on the install is going ahead. =====

if [ -n "$LEGACY" ] && [ -d "$LEGACY" ]; then
    (cd "$LEGACY" && docker compose down 2>/dev/null) || true
    docker rm -f ipfailover-agent >/dev/null 2>&1 || true
    if [ "${1:-}" = "--upgrade" ] && [ ! -f "$DIR/data/state.json" ]; then
        mkdir -p "$DIR/data"
        # Identity and state only: v2's unsigned staged agent.php is left behind on purpose.
        for f in state.json agent-key.json status.json machine-id log-spool.json update-state.json current-release.json; do
            if [ -f "$LEGACY/data/$f" ]; then mv "$LEGACY/data/$f" "$DIR/data/$f"; fi
        done
        say "Moved this host's existing identity from $LEGACY."
    fi
    # Reprovision/fresh install: the old identity is destroyed with the folder.
    find "$LEGACY" -type f \( -name agent-key.json -o -name state.json \) -exec sh -c 'command -v shred >/dev/null 2>&1 && shred -u "$1" || rm -f "$1"' _ {} \;
    rm -rf "$LEGACY"
    say "Removed the old install at $LEGACY."
fi

say "Installing the DynAllow agent into $DIR"
mkdir -p "$DIR/data" "$DIR/app"
if [ -f "$DIR/docker-compose.yml" ]; then (cd "$DIR" && docker compose down); fi
if [ "${1:-}" = "--reprovision" ]; then
    (cd "$DIR" && docker compose down 2>/dev/null) || true
    for f in agent-key.json state.json status.json agent.php; do
        [ -f "$DIR/data/$f" ] && { command -v shred >/dev/null 2>&1 && shred -u "$DIR/data/$f" || rm -f "$DIR/data/$f"; }
    done
    say "Old identity destroyed."
fi

base64 -d > "$DIR/app/agent.php" <<'B64'
__AGENT_PHP_B64__
B64
base64 -d > "$DIR/app/launcher.php" <<'B64'
__LAUNCHER_B64__
B64
base64 -d > "$DIR/app/release.php" <<'B64'
__VERIFIER_B64__
B64
base64 -d > "$DIR/app/release-public.pem" <<'B64'
__RELEASE_PUBLIC_B64__
B64
base64 -d > "$DIR/docker-compose.yml" <<'B64'
__COMPOSE_B64__
B64
if [ "${1:-}" != "--upgrade" ]; then
umask 077
base64 -d > "$DIR/data/provisioning.json" <<'B64'
__PROFILE_B64__
B64
umask 022
fi

# No /etc/machine-id on this host: drop that mount, or Docker would create a directory there.
[ -f /etc/machine-id ] || sed -i '/host-machine-id/d' "$DIR/docker-compose.yml"
chown root:root "$DIR"
chown -R root:root "$DIR/app"
chmod 755 "$DIR" "$DIR/app"
chown -R 65534:65534 "$DIR/data"
chmod 700 "$DIR/data"
chmod 644 "$DIR/app/"* "$DIR/docker-compose.yml"

burn
cd "$DIR"
docker compose up -d
say ""
say "Waiting for the first check-in (up to 2 minutes)..."
i=0
while [ $i -lt 40 ]; do
    sleep 3; i=$((i + 1))
    if out=$(docker compose exec -T dynallow-agent php /app/launcher.php health 2>/dev/null); then
        say ""; say "  INSTALLED. $out"; say "  Check health any time:  docker ps   (look for 'healthy')"; exit 0
    fi
    case "${out:-}" in *"IP held"*|*"DNS "*|*"enroll"*|*"not valid"*|*"expired"*) break ;; esac
done
say ""
say "  Installed, but not healthy yet: ${out:-no status}"
say "  See what it is doing:  cd $DIR && docker compose logs --tail 30"
